patch:
diff --git a/recreate-no-var/repro.js b/recreate-no-var/repro.js
new file mode 100644
index 0000000..8dd8d92
--- /dev/null
+++ b/recreate-no-var/repro.js
@@ -0,0 +1,55 @@
+"use strict";
+
+/*
+ * Reproduction for the report "[no-var] Fix causes ReferenceError".
+ *
+ * Usage (from the repo root):
+ *   node recreate-no-var/repro.js                      # lints/fixes with this checkout
+ *   node recreate-no-var/repro.js <path-to-eslint-pkg> # lints/fixes with another eslint install
+ *
+ * Exits with status 1 if the autofix was applied and the fixed module throws a
+ * ReferenceError (the reported symptom), 0 otherwise.
+ */
+
+const path = require("node:path");
+
+const eslintPath = process.argv[2]
+	? path.resolve(process.argv[2])
+	: path.resolve(__dirname, "../lib/api");
+const { Linter } = require(eslintPath);
+
+const code = `export function a() {
+    console.log(o);
+    var o;
+    return o;
+}
+`;
+
+const config = [{ rules: { "no-var": ["error"] } }];
+
+(async () => {
+	const linter = new Linter();
+	const result = linter.verifyAndFix(code, config);
+
+	console.log(`eslint under test: ${eslintPath}`);
+	console.log(`fixed:   ${result.fixed}`);
+	console.log(`output:\n${result.output}`);
+	console.log(
+		`remaining messages: ${result.messages.map(m => `${m.line}:${m.column} ${m.message}`).join("; ") || "(none)"}`,
+	);
+
+	try {
+		const mod = await import(
+			`data:text/javascript,${encodeURIComponent(result.output)}`
+		);
+
+		mod.a();
+		console.log("running the output: no error");
+	} catch (e) {
+		console.log(`running the output: ${e.name}: ${e.message}`);
+		if (e instanceof ReferenceError && result.fixed) {
+			console.log("REPRODUCED: autofix turned working code into code that throws");
+			process.exitCode = 1;
+		}
+	}
+})();
